<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';auth();
header('Cache-Control: private, no-store');
$h=static fn($s)=>htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$allowed=['top','bottom','side','crumb','scan'];
$angle=(string)($_GET['angle']??'all');if($angle!=='all'&&!in_array($angle,$allowed,true))$angle='all';
$rid=filter_var($_GET['recipe_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:null;
$bid=filter_var($_GET['batch_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:null;
$eid=filter_var($_GET['evidence_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:null;
$page=max(1,min(10000,(int)($_GET['page']??1)));$limit=36;
$where=["m.kind IN ('top','bottom','side','crumb','scan')"];$args=[];
if($angle!=='all'){$where[]='m.kind=?';$args[]=$angle;}
if($rid){$where[]='e.recipe_id=?';$args[]=$rid;}
if($bid){$where[]='e.batch_id=?';$args[]=$bid;}
if($eid){$where[]='e.id=?';$args[]=$eid;}
$filter=' WHERE '.implode(' AND ',$where);
$join=' FROM media m JOIN evidence e ON e.id=m.evidence_id LEFT JOIN recipes r ON r.id=e.recipe_id LEFT JOIN dough_batches b ON b.id=e.batch_id';
$total=(int)query('SELECT COUNT(*)'.$join.$filter,$args)->fetchColumn();
$pages=max(1,(int)ceil($total/$limit));$page=min($page,$pages);$offset=($page-1)*$limit;
$photos=query('SELECT m.id,m.kind,m.original_name,m.created_at,e.id AS evidence_id,e.label,e.pizza_size_in,r.name AS recipe_name,b.batch_code'.$join.$filter.' ORDER BY m.id DESC LIMIT '.$limit.' OFFSET '.$offset,$args)->fetchAll();
$recipes=query('SELECT id,name FROM recipes ORDER BY name')->fetchAll();
$batches=query('SELECT b.id,b.batch_code,r.name AS recipe_name FROM dough_batches b JOIN recipes r ON r.id=b.recipe_id ORDER BY b.id DESC LIMIT 500')->fetchAll();
$params=['angle'=>$angle];if($rid)$params['recipe_id']=$rid;if($bid)$params['batch_id']=$bid;if($eid)$params['evidence_id']=$eid;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#10151c"><title>Pizza Lab · Evidence Gallery</title><link rel="stylesheet" href="assets/style.css?v=1.5.3"><style>.gallery-shell{max-width:1400px;margin:auto;padding:clamp(16px,4vw,48px)}.gallery-filter{display:flex;flex-wrap:wrap;gap:12px;align-items:end}.gallery-filter label{min-width:160px;flex:1}.gallery-tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:16px;margin:24px 0}.gallery-tile{border:1px solid #3e4754;border-radius:14px;overflow:hidden;background:#1c2430}.gallery-tile img{width:100%;height:205px;object-fit:cover;display:block}.gallery-meta{padding:13px}.gallery-meta p{margin:5px 0}.gallery-pages{display:flex;gap:14px;align-items:center}</style></head><body><main class="gallery-shell"><p class="overline">EVIDENCE LIBRARY</p><h1>Pizza image gallery</h1><p>Every photo remains linked to its pizza test, recipe and dough batch. Images are available only to signed-in team members.</p><p><a href="index.php">← Pizza Lab workspace</a> · <a href="agent_chat.php">Agent Chat</a></p><section class="panel"><form class="gallery-filter" method="get"><label>View angle<select name="angle"><option value="all">All views</option><?php foreach($allowed as $view):?><option value="<?=$h($view)?>" <?=$angle===$view?'selected':''?>><?=ucfirst($h($view))?></option><?php endforeach;?></select></label><label>Recipe<select name="recipe_id"><option value="">All recipes</option><?php foreach($recipes as $r):?><option value="<?=$h($r['id'])?>" <?=$rid===(int)$r['id']?'selected':''?>><?=$h($r['name'])?></option><?php endforeach;?></select></label><label>Dough batch<select name="batch_id"><option value="">All batches</option><?php foreach($batches as $b):?><option value="<?=$h($b['id'])?>" <?=$bid===(int)$b['id']?'selected':''?>><?=$h($b['batch_code'].' · '.$b['recipe_name'])?></option><?php endforeach;?></select></label><label>Pizza test #<input name="evidence_id" type="number" min="1" value="<?=$h($eid?:'')?>" placeholder="Any pizza"></label><button class="primary">Filter images</button><a href="gallery.php">Clear</a></form></section><p class="muted"><?=number_format($total)?> photos · Page <?=$page?> of <?=$pages?></p><div class="gallery-tiles"><?php foreach($photos as $m):?><article class="gallery-tile"><a href="media.php?id=<?=$h($m['id'])?>" target="_blank" rel="noopener noreferrer" title="View original"><img src="media.php?id=<?=$h($m['id'])?>" alt="<?=$h(ucfirst($m['kind']).' angle for '.$m['label'])?>" loading="lazy"></a><div class="gallery-meta"><b><?=$h($m['label'])?></b> <span class="pill"><?=$h($m['kind'])?></span><p class="small muted"><?=$h($m['recipe_name']??'No recipe')?> · <?=$h($m['batch_code']??'No batch')?></p><p class="small muted">Pizza #<?=$h($m['evidence_id'])?> · <?=$h($m['created_at'])?></p><a href="index.php?evidence_id=<?=$h($m['evidence_id'])?>">Open pizza workspace</a></div></article><?php endforeach;?></div><?php if(!$photos):?><div class="empty">No photographs match those filters.</div><?php endif;?><nav class="gallery-pages"><?php if($page>1):?><a href="?<?=$h(http_build_query($params+['page'=>$page-1]))?>">← Previous</a><?php endif;?><span>Page <?=$page?> / <?=$pages?></span><?php if($page<$pages):?><a href="?<?=$h(http_build_query($params+['page'=>$page+1]))?>">Next →</a><?php endif;?></nav></main></body></html>
